import type { SVGProps } from 'react';

type IconProps = SVGProps<SVGSVGElement>;

function Glyph({
  d,
  opacity,
  fillRule,
}: {
  d: string;
  opacity?: number;
  fillRule?: 'evenodd';
}) {
  return (
    <path d={d} fill="currentColor" fillRule={fillRule} opacity={opacity} />
  );
}

function Svg({ children, ...props }: IconProps) {
  return (
    <svg
      aria-hidden="true"
      fill="currentColor"
      viewBox="0 0 1024 1024"
      {...props}
    >
      {children}
    </svg>
  );
}

function OutlineSvg({ children, ...props }: IconProps) {
  return (
    <svg
      aria-hidden="true"
      fill="none"
      stroke="currentColor"
      strokeLinejoin="round"
      strokeWidth="80.64"
      viewBox="0 0 1024 1024"
      {...props}
    >
      {children}
    </svg>
  );
}

